// Column route planning for the world planning UI: a faithful port of
// `api/app/engine/routing.py` (`find_route`, `route_pulses`, `travel_eta`) and of the
// cost model `GameMap.column_costs` in `api/app/engine/models.py`. The server is the
// authority; this predicts the route a travel order will take. Ties must resolve
// exactly as in Python (same heap key, heuristic, relaxation rule and neighbour
// order), so `routing.test.ts` checks it against a fixture generated by
// `api/scripts/route_fixture.py`. Change one side, regenerate and re-run the other.

import { AXIAL_DIRECTIONS, type Axial } from "@/board/hex";

import type { WorldMap } from "./worldMap";
import { axialToOffset } from "./worldMap";

/** `COLUMN_RULES` defaults in `api/app/engine/stats.py` (`ColumnRules`). */
export const COLUMN_RULES = {
  pulsesPerTurn: 16,
  packPulses: 4,
  roadStepPulses: 1,
  offroadStepPulses: 2,
} as const;

/** `TERRAIN_STATS[terrain].passable` in `api/app/engine/stats.py`. */
const IMPASSABLE_TERRAIN: ReadonlySet<string> = new Set(["river"]);

const CHEAPEST_STEP = Math.min(COLUMN_RULES.roadStepPulses, COLUMN_RULES.offroadStepPulses);

export interface ColumnCosts {
  readonly width: number;
  readonly height: number;
  /** Pulses to enter each offset cell, row-major; 0 = impassable. */
  readonly pulses: Int8Array;
}

/** Per-hex column step costs for a map (impassable hexes cost 0). Build once per map. */
export function columnCosts(map: WorldMap): ColumnCosts {
  const pulses = new Int8Array(map.width * map.height);
  map.hexes.forEach((hex, i) => {
    if (IMPASSABLE_TERRAIN.has(hex.terrain)) return;
    pulses[i] = hex.road ? COLUMN_RULES.roadStepPulses : COLUMN_RULES.offroadStepPulses;
  });
  return { width: map.width, height: map.height, pulses };
}

/** Offset cell index of axial `(q, r)`, or -1 when off the map. */
function cellOf(costs: ColumnCosts, q: number, r: number): number {
  const { col, row } = axialToOffset({ q, r });
  if (col < 0 || col >= costs.width || row < 0 || row >= costs.height) return -1;
  return row * costs.width + col;
}

function axialOfCell(costs: ColumnCosts, cell: number): Axial {
  const col = cell % costs.width;
  const row = (cell - col) / costs.width;
  return { q: col, r: row - (col - (col & 1)) / 2 };
}

/**
 * The least-cost column route from `origin` through `via` to `destination`: the hexes
 * to enter in order (`origin` excluded), `null` if any leg is unreachable, `[]` when
 * every stop is `origin`. Each leg is planned independently.
 */
export function findRoute(
  costs: ColumnCosts,
  origin: Axial,
  destination: Axial,
  via: readonly Axial[] = [],
): Axial[] | null {
  const stops = [origin, ...via, destination];
  const route: Axial[] = [];
  for (let i = 0; i + 1 < stops.length; i++) {
    const leg = astar(costs, stops[i], stops[i + 1]);
    if (leg === null) return null;
    for (const hex of leg) route.push(hex);
  }
  return route;
}

/** Total column pulses to march `route` on an open road (no waiting). */
export function routePulses(costs: ColumnCosts, route: readonly Axial[]): number {
  let total = 0;
  for (const { q, r } of route) total += costs.pulses[cellOf(costs, q, r)];
  return total;
}

/**
 * Turns a column needs to march `route`, counting the turn it arrives: a step fires if
 * the turn's remaining pulses cover its cost, and unspent pulses are lost at turn end.
 * A deployed unit (`packed: false`) spends the opening pulses of its first turn packing.
 */
export function travelEta(
  costs: ColumnCosts,
  route: readonly Axial[],
  { packed }: { packed: boolean },
): number {
  let turns = 0;
  let index = 0;
  let budget = COLUMN_RULES.pulsesPerTurn - (packed ? 0 : COLUMN_RULES.packPulses);
  while (index < route.length) {
    turns += 1;
    let spent = 0;
    while (index < route.length) {
      const cost = costs.pulses[cellOf(costs, route[index].q, route[index].r)];
      if (spent + cost > budget) break;
      spent += cost;
      index += 1;
    }
    budget = COLUMN_RULES.pulsesPerTurn;
  }
  return turns;
}

/**
 * Binary min-heap of A* frontier entries over parallel typed arrays. Order is the
 * Python heap key `(g + h, -g, q, r)`: lowest estimate, then deepest, then `q`, then
 * `r`. For one column `r` rises with the offset row, so `(col, row)` orders the same
 * as `(q, r)`.
 */
class Frontier {
  private f: Int32Array<ArrayBuffer> = new Int32Array(1024);
  private g: Int32Array<ArrayBuffer> = new Int32Array(1024);
  private cell: Int32Array<ArrayBuffer> = new Int32Array(1024);
  size = 0;

  constructor(private readonly width: number) {}

  private less(i: number, j: number): boolean {
    if (this.f[i] !== this.f[j]) return this.f[i] < this.f[j];
    if (this.g[i] !== this.g[j]) return this.g[i] > this.g[j];
    const ci = this.cell[i] % this.width;
    const cj = this.cell[j] % this.width;
    if (ci !== cj) return ci < cj;
    return this.cell[i] < this.cell[j]; // same column: smaller row first
  }

  private swap(i: number, j: number): void {
    const f = this.f[i];
    const g = this.g[i];
    const c = this.cell[i];
    this.f[i] = this.f[j];
    this.g[i] = this.g[j];
    this.cell[i] = this.cell[j];
    this.f[j] = f;
    this.g[j] = g;
    this.cell[j] = c;
  }

  private grow(): void {
    const widen = (a: Int32Array<ArrayBuffer>): Int32Array<ArrayBuffer> => {
      const b = new Int32Array(a.length * 2);
      b.set(a);
      return b;
    };
    this.f = widen(this.f);
    this.g = widen(this.g);
    this.cell = widen(this.cell);
  }

  push(f: number, g: number, cell: number): void {
    if (this.size === this.f.length) this.grow();
    let i = this.size++;
    this.f[i] = f;
    this.g[i] = g;
    this.cell[i] = cell;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (!this.less(i, parent)) break;
      this.swap(i, parent);
      i = parent;
    }
  }

  /** Remove the minimum entry, returning its `[g, cell]` via the `top*` fields. */
  topG = 0;
  topCell = 0;
  pop(): void {
    this.topG = this.g[0];
    this.topCell = this.cell[0];
    const last = --this.size;
    if (last > 0) {
      this.f[0] = this.f[last];
      this.g[0] = this.g[last];
      this.cell[0] = this.cell[last];
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < last && this.less(l, m)) m = l;
        if (r < last && this.less(r, m)) m = r;
        if (m === i) break;
        this.swap(i, m);
        i = m;
      }
    }
  }
}

/** A* from `start` to `goal`; the hexes entered (`start` excluded), or `null`. */
function astar(costs: ColumnCosts, start: Axial, goal: Axial): Axial[] | null {
  if (start.q === goal.q && start.r === goal.r) return [];
  const goalCell = cellOf(costs, goal.q, goal.r);
  if (goalCell < 0 || costs.pulses[goalCell] === 0) return null;
  const startCell = cellOf(costs, start.q, start.r);
  if (startCell < 0) throw new Error(`route start (${start.q}, ${start.r}) is off the map`);

  const { width, pulses } = costs;
  const size = pulses.length;
  const heuristic = (q: number, r: number): number => {
    const dq = q - goal.q;
    const dr = r - goal.r;
    return CHEAPEST_STEP * ((Math.abs(dq) + Math.abs(dq + dr) + Math.abs(dr)) >> 1);
  };

  const best = new Int32Array(size).fill(-1); // -1 = never reached
  const cameFrom = new Int32Array(size).fill(-1);
  const closed = new Uint8Array(size);
  const frontier = new Frontier(width);
  best[startCell] = 0;
  frontier.push(heuristic(start.q, start.r), 0, startCell);

  while (frontier.size > 0) {
    frontier.pop();
    const current = frontier.topCell;
    if (current === goalCell) return walkBack(costs, cameFrom, startCell, goalCell);
    if (closed[current]) continue;
    closed[current] = 1;
    const g = frontier.topG;
    const { q, r } = axialOfCell(costs, current);
    for (const d of AXIAL_DIRECTIONS) {
      const nq = q + d.q;
      const nr = r + d.r;
      const col = nq;
      const row = nr + (nq - (nq & 1)) / 2;
      if (col < 0 || col >= width || row < 0 || row >= costs.height) continue;
      const next = row * width + col;
      const step = pulses[next];
      if (step === 0 || closed[next]) continue;
      const tentative = g + step;
      if (best[next] === -1 || tentative < best[next]) {
        best[next] = tentative;
        cameFrom[next] = current;
        frontier.push(tentative + heuristic(nq, nr), tentative, next);
      }
    }
  }
  return null;
}

function walkBack(
  costs: ColumnCosts,
  cameFrom: Int32Array,
  startCell: number,
  goalCell: number,
): Axial[] {
  const path: Axial[] = [];
  for (let cell = goalCell; cell !== startCell; cell = cameFrom[cell]) {
    path.push(axialOfCell(costs, cell));
  }
  return path.reverse();
}
